#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "deriche.h"


/* Array initialization. */
static
void init_array (int w, int h, DATA_TYPE* alpha,
		 DATA_TYPE POLYBENCH_2D(imgIn,W,H,w,h),
		 DATA_TYPE POLYBENCH_2D(imgOut,W,H,w,h))
{
  int i, j;

  *alpha=0.25; //parameter of the filter

  //input should be between 0 and 1 (grayscale image pixel)
  for (i = 0; i < w; i++)
     for (j = 0; j < h; j++)
	imgIn[i][j] = (DATA_TYPE) ((313*i+991*j)%65536) / 65535.0f;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int w, int h,
		 DATA_TYPE POLYBENCH_2D(imgOut,W,H,w,h))

{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("imgOut");
  for (i = 0; i < w; i++)
    for (j = 0; j < h; j++) {
      if ((i * h + j) % 20 == 0) fprintf(POLYBENCH_DUMP_TARGET, "\n");
      fprintf(POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, imgOut[i][j]);
    }
  POLYBENCH_DUMP_END("imgOut");
  POLYBENCH_DUMP_FINISH;
}



/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* Original code provided by Gael Deest */
static void __attribute__((noinline))
kernel_deriche(int w, int h, DATA_TYPE alpha,
       DATA_TYPE POLYBENCH_2D(imgIn, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(imgOut, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y1, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y2, W, H, w, h)) {
    int i,j;

    /* Filter coefficients. */
    DATA_TYPE k;
    DATA_TYPE a1, a2, a3, a4, a5, a6, a7, a8;
    DATA_TYPE b1, b2, c1, c2;

#pragma scop
    /* Coefficient computation (unchanged). */
    k = (SCALAR_VAL(1.0)-EXP_FUN(-alpha)) *
        (SCALAR_VAL(1.0)-EXP_FUN(-alpha)) /
        (SCALAR_VAL(1.0)+SCALAR_VAL(2.0)*alpha*EXP_FUN(-alpha)
         -EXP_FUN(SCALAR_VAL(2.0)*alpha));
    a1 = a5 = k;
    a2 = a6 = k*EXP_FUN(-alpha)*(alpha-SCALAR_VAL(1.0));
    a3 = a7 = k*EXP_FUN(-alpha)*(alpha+SCALAR_VAL(1.0));
    a4 = a8 = -k*EXP_FUN(SCALAR_VAL(-2.0)*alpha);
    b1 =  POW_FUN(SCALAR_VAL(2.0),-alpha);
    b2 = -EXP_FUN(SCALAR_VAL(-2.0)*alpha);
    c1 = c2 = SCALAR_VAL(1.0);

    /* Use explicit local copies of the problem sizes to avoid repeatedly
       expanding the PolyBench macros. */
    const int W_ = _PB_W;
    const int H_ = _PB_H;

    /* ------------------------------------------------------------------ */
    /* Horizontal processing: forward and backward recursions per row.
       We fuse the forward pass, backward pass, and first combination
       into a single outer loop over rows to improve cache reuse and
       reduce the number of full-image passes.                          */
    /* ------------------------------------------------------------------ */
    for (i = 0; i < W_; i++) {
        /* Row pointers improve locality and reduce address arithmetic.
           'restrict' helps the compiler with alias analysis. */
        DATA_TYPE *restrict imgIn_row  = imgIn[i];
        DATA_TYPE *restrict y1_row     = y1[i];
        DATA_TYPE *restrict y2_row     = y2[i];
        DATA_TYPE *restrict imgOut_row = imgOut[i];

        /* Forward horizontal recursion: j increasing. */
        DATA_TYPE xm1 = SCALAR_VAL(0.0);
        DATA_TYPE ym1 = SCALAR_VAL(0.0);
        DATA_TYPE ym2 = SCALAR_VAL(0.0);

        for (j = 0; j < H_; j++) {
            DATA_TYPE x0 = imgIn_row[j];
            DATA_TYPE y0 = a1 * x0 + a2 * xm1 + b1 * ym1 + b2 * ym2;
            y1_row[j] = y0;
            xm1 = x0;
            ym2 = ym1;
            ym1 = y0;
        }

        /* Backward horizontal recursion: j decreasing.
           We fuse the first horizontal combination:
             imgOut = c1 * (y1 + y2)
           directly into this loop to avoid an extra image-wide pass. */
        DATA_TYPE xp1 = SCALAR_VAL(0.0);
        DATA_TYPE xp2 = SCALAR_VAL(0.0);
        DATA_TYPE yp1 = SCALAR_VAL(0.0);
        DATA_TYPE yp2 = SCALAR_VAL(0.0);

        for (j = H_ - 1; j >= 0; j--) {
            DATA_TYPE y0 = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
            y2_row[j] = y0;

            xp2 = xp1;
            xp1 = imgIn_row[j];
            yp2 = yp1;
            yp1 = y0;

            /* Horizontal combination (uses already-computed y1_row[j]). */
            imgOut_row[j] = c1 * (y1_row[j] + y0);
        }
    }

    /* ------------------------------------------------------------------ */
    /* Vertical processing.
       Original code processes each column independently with inner loops
       over rows (i). That leads to poor spatial locality because the
       memory layout is row-major (j is contiguous).
       We transform the loops so that:
         - The inner loop iterates over columns j (contiguous in memory).
         - The recurrences along i (rows) are preserved by keeping
           per-column state in small temporary arrays.
       This improves cache behavior and allows the compiler to vectorize
       over j (across columns).                                          */
    /* ------------------------------------------------------------------ */

    /* Per-column state for forward vertical recursion. */
    DATA_TYPE tm1_col[H_];
    DATA_TYPE ym1_col[H_];
    DATA_TYPE ym2_col[H_];

    /* Initialize vertical forward state: for each column j,
       tm1 = ym1 = ym2 = 0 at i = 0. */
    for (j = 0; j < H_; j++) {
        tm1_col[j] = SCALAR_VAL(0.0);
        ym1_col[j] = SCALAR_VAL(0.0);
        ym2_col[j] = SCALAR_VAL(0.0);
    }

    /* Forward vertical recursion: rows i increasing, columns j in the
       inner loop for unit-stride accesses. */
    for (i = 0; i < W_; i++) {
        DATA_TYPE *restrict imgOut_row = imgOut[i];
        DATA_TYPE *restrict y1_row     = y1[i];

        for (j = 0; j < H_; j++) {
            DATA_TYPE x0   = imgOut_row[j];
            DATA_TYPE xm1v = tm1_col[j];
            DATA_TYPE ym1v = ym1_col[j];
            DATA_TYPE ym2v = ym2_col[j];

            DATA_TYPE y0 = a5 * x0 + a6 * xm1v + b1 * ym1v + b2 * ym2v;
            y1_row[j] = y0;

            tm1_col[j] = x0;
            ym2_col[j] = ym1v;
            ym1_col[j] = y0;
        }
    }

    /* Per-column state for backward vertical recursion. */
    DATA_TYPE tp1_col[H_];
    DATA_TYPE tp2_col[H_];
    DATA_TYPE yp1_col[H_];
    DATA_TYPE yp2_col[H_];

    /* Initialize vertical backward state: for each column j,
       tp1 = tp2 = yp1 = yp2 = 0 at i = W_-1. */
    for (j = 0; j < H_; j++) {
        tp1_col[j] = SCALAR_VAL(0.0);
        tp2_col[j] = SCALAR_VAL(0.0);
        yp1_col[j] = SCALAR_VAL(0.0);
        yp2_col[j] = SCALAR_VAL(0.0);
    }

    /* Backward vertical recursion: rows i decreasing, columns j in the
       inner loop. We fuse the final combination
         imgOut = c2 * (y1 + y2)
       into this loop to eliminate an extra image sweep. */
    for (i = W_ - 1; i >= 0; i--) {
        DATA_TYPE *restrict imgOut_row = imgOut[i];
        DATA_TYPE *restrict y1_row     = y1[i];
        DATA_TYPE *restrict y2_row     = y2[i];

        for (j = 0; j < H_; j++) {
            DATA_TYPE tp1v = tp1_col[j];
            DATA_TYPE tp2v = tp2_col[j];
            DATA_TYPE yp1v = yp1_col[j];
            DATA_TYPE yp2v = yp2_col[j];

            DATA_TYPE y0 = a7 * tp1v + a8 * tp2v + b1 * yp1v + b2 * yp2v;
            y2_row[j] = y0;

            /* Update per-column recursion state.  Note that we read
               imgOut_row[j] (the intermediate horizontal result) before
               overwriting it with the final value, so the recurrence uses
               exactly the same inputs as the original code. */
            tp2_col[j] = tp1v;
            tp1_col[j] = imgOut_row[j];
            yp2_col[j] = yp1v;
            yp1_col[j] = y0;

            /* Final vertical combination. */
            imgOut_row[j] = c2 * (y1_row[j] + y0);
        }
    }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int w = W;
  int h = H;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(imgIn, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(imgOut, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(y1, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(y2, DATA_TYPE, W, H, w, h);


  /* Initialize array(s). */
  init_array (w, h, &alpha, POLYBENCH_ARRAY(imgIn), POLYBENCH_ARRAY(imgOut));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_deriche (w, h, alpha, POLYBENCH_ARRAY(imgIn), POLYBENCH_ARRAY(imgOut), POLYBENCH_ARRAY(y1), POLYBENCH_ARRAY(y2));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(w, h, POLYBENCH_ARRAY(imgOut)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(imgIn);
  POLYBENCH_FREE_ARRAY(imgOut);
  POLYBENCH_FREE_ARRAY(y1);
  POLYBENCH_FREE_ARRAY(y2);

  return 0;
}
