/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/* Original code provided by Gael Deest

   Optimizations:
   - Precompute and reuse exponential terms.
   - Improve data locality using row pointers.
   - Fuse passes to reduce the number of full-array traversals:
       * Horizontal stage: fuse backward pass with first combination.
       * Vertical stage: fuse backward pass with final combination.
   - Avoid storing horizontal/vertical y2 intermediates, which are never read.
   These transformations preserve the mathematical result while cutting
   memory traffic and improving cache behavior.
*/
static
void kernel_deriche[[gnu::flatten, gnu::noinline]](int w, int h, DATA_TYPE alpha,
       DATA_TYPE POLYBENCH_2D(imgIn, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(imgOut, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y1, W, H, w, h),
       DATA_TYPE POLYBENCH_2D(y2, W, H, w, h)) {
    int i,j;
    DATA_TYPE xm1, tm1, ym1, ym2;
    DATA_TYPE xp1, xp2;
    DATA_TYPE tp1, tp2;
    DATA_TYPE yp1, yp2;

    DATA_TYPE k;
    DATA_TYPE a1, a2, a3, a4, a5, a6, a7, a8;
    DATA_TYPE b1, b2, c1, c2;

#pragma scop
    /* Cache loop bounds locally to avoid repeated macro expansion and
       to give the compiler clearer, simple loop limits. */
    const int wsize = _PB_W;
    const int hsize = _PB_H;

    /* Precompute some scalars and exponentials once. */
    const DATA_TYPE one = SCALAR_VAL(1.0);
    const DATA_TYPE two = SCALAR_VAL(2.0);

    const DATA_TYPE ea    = EXP_FUN(-alpha);        /* exp(-alpha)   */
    const DATA_TYPE e2a   = EXP_FUN(two * alpha);   /* exp( 2*alpha) */
    const DATA_TYPE em2a  = EXP_FUN(-two * alpha);  /* exp(-2*alpha) */

    k  = (one - ea) * (one - ea) /
         (one + two * alpha * ea - e2a);

    a1 = a5 = k;
    a2 = a6 = k * ea * (alpha - one);
    a3 = a7 = k * ea * (alpha + one);
    a4 = a8 = -k * em2a;

    b1 = POW_FUN(two, -alpha);
    b2 = -em2a;
    c1 = c2 = one;

    /* =========================
       Horizontal filtering pass
       =========================
       For each row i:
         1) Forward recursion (writes to y1[i][*])
         2) Backward recursion (does NOT store y2) + combine with y1
            to produce the horizontally filtered result in imgOut[i][*].

       Note: The original code stored horizontal y2 and then had a
       separate pass imgOut = c1 * (y1 + y2). Since horizontal y2 is
       never used afterwards (only the sum y1+y2 is), we can avoid
       storing y2 and fuse those passes safely.
    */
    for (i = 0; i < wsize; i++) {
        DATA_TYPE* __restrict imgIn_i  = imgIn[i];
        DATA_TYPE* __restrict imgOut_i = imgOut[i];
        DATA_TYPE* __restrict y1_i     = y1[i];

        /* Forward horizontal recursion along row i (j increasing). */
        xm1 = SCALAR_VAL(0.0);
        ym1 = SCALAR_VAL(0.0);
        ym2 = SCALAR_VAL(0.0);

        for (j = 0; j < hsize; j++) {
            DATA_TYPE x = imgIn_i[j];
            DATA_TYPE y = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;

            y1_i[j] = y;

            xm1 = x;
            ym2 = ym1;
            ym1 = y;
        }

        /* Backward horizontal recursion along row i (j decreasing)
           plus combination with the forward result.

           This reproduces the original recurrence for y2 but does not
           store it into the y2 array, because y2 from this horizontal
           stage is never read later: only c1 * (y1 + y2) is required. */
        xp1 = SCALAR_VAL(0.0);
        xp2 = SCALAR_VAL(0.0);
        yp1 = SCALAR_VAL(0.0);
        yp2 = SCALAR_VAL(0.0);

        for (j = hsize - 1; j >= 0; j--) {
            DATA_TYPE x  = imgIn_i[j];
            DATA_TYPE yb = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
            DATA_TYPE yf = y1_i[j]; /* forward component already computed */

            imgOut_i[j] = c1 * (yf + yb); /* final horizontal result */

            xp2 = xp1;
            xp1 = x;
            yp2 = yp1;
            yp1 = yb;
        }
    }

    /* =======================
       Vertical filtering pass
       =======================
       We now take the horizontally filtered image stored in imgOut
       as input and apply the vertical Deriche filter.

       For each column j:
         1) Forward recursion along i (writes to y1[*][j])
         2) Backward recursion along i (does NOT store y2) +
            combine to write the final 2D result back into imgOut.

       As with the horizontal stage, vertical y2 is never needed by
       anyone after the final combination, so we avoid storing it.
    */
    for (j = 0; j < hsize; j++) {
        /* Forward vertical recursion along column j (i increasing). */
        tm1 = SCALAR_VAL(0.0);
        ym1 = SCALAR_VAL(0.0);
        ym2 = SCALAR_VAL(0.0);

        for (i = 0; i < wsize; i++) {
            DATA_TYPE x = imgOut[i][j]; /* horizontally filtered input */
            DATA_TYPE y = a5 * x + a6 * tm1 + b1 * ym1 + b2 * ym2;

            y1[i][j] = y;

            tm1 = x;
            ym2 = ym1;
            ym1 = y;
        }

        /* Backward vertical recursion along column j (i decreasing)
           plus final combination into imgOut. */
        tp1 = SCALAR_VAL(0.0);
        tp2 = SCALAR_VAL(0.0);
        yp1 = SCALAR_VAL(0.0);
        yp2 = SCALAR_VAL(0.0);

        for (i = wsize - 1; i >= 0; i--) {
            DATA_TYPE x  = imgOut[i][j];        /* still horizontal result */
            DATA_TYPE yb = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
            DATA_TYPE yf = y1[i][j];            /* forward vertical component */

            imgOut[i][j] = c2 * (yf + yb);      /* final output */

            tp2 = tp1;
            tp1 = x;
            yp2 = yp1;
            yp1 = yb;
        }
    }

#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int w = W;
  int h = H;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  POLYBENCH_2D_ARRAY_DECL(imgIn, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(imgOut, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(y1, DATA_TYPE, W, H, w, h);
  POLYBENCH_2D_ARRAY_DECL(y2, DATA_TYPE, W, H, w, h);


  /* Initialize array(s). */
  init_array (w, h, &alpha, POLYBENCH_ARRAY(imgIn), POLYBENCH_ARRAY(imgOut));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_deriche (w, h, alpha, POLYBENCH_ARRAY(imgIn), POLYBENCH_ARRAY(imgOut), POLYBENCH_ARRAY(y1), POLYBENCH_ARRAY(y2));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(w, h, POLYBENCH_ARRAY(imgOut)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(imgIn);
  POLYBENCH_FREE_ARRAY(imgOut);
  POLYBENCH_FREE_ARRAY(y1);
  POLYBENCH_FREE_ARRAY(y2);

  return 0;
}
