 * Optimized for:
 *  - Better cache locality (row- and column-wise fusion of passes)
 *  - Fewer redundant transcendental calls
 *  - Improved alias analysis via restrict-qualified local pointers
 *  - Reduced indexing overhead via pointer arithmetic
 */
static
void kernel_deriche [[gnu::flatten, gnu::noinline]] (
    int w, int h, DATA_TYPE alpha,
    DATA_TYPE POLYBENCH_2D(imgIn,  W, H, w, h),
    DATA_TYPE POLYBENCH_2D(imgOut, W, H, w, h),
    DATA_TYPE POLYBENCH_2D(y1,     W, H, w, h),
    DATA_TYPE POLYBENCH_2D(y2,     W, H, w, h))
