  const DATA_TYPE a1 = k;
  const DATA_TYPE a5 = k;

  const DATA_TYPE tmp = k * ea;
  const DATA_TYPE a2  = tmp * (alpha - one);
  const DATA_TYPE a6  = a2;
  const DATA_TYPE a3  = tmp * (alpha + one);
  const DATA_TYPE a7  = a3;
  const DATA_TYPE a4  = -k * e2a_neg;
  const DATA_TYPE a8  = a4;

  const DATA_TYPE b1 = pow2_ma;
  const DATA_TYPE b2 = -e2a_neg;
  const DATA_TYPE c1 = one;
  const DATA_TYPE c2 = one;

  /* -------------------- Horizontal pass (row-wise) -------------------- */
  /* For each row:
   *   - run forward recursion (writes y1)
   *   - run backward recursion (writes y2)
   *   - combine to produce intermediate imgOut
   *
   * This per-row fusion improves temporal locality: imgIn, y1, y2, imgOut
   * for a given row stay hot in cache.
   */
  for (int i = 0; i < w_; ++i)
  {
    /* Row pointers with restrict to help alias analysis.
     * Each pointer refers to a distinct array region.
     */
    DATA_TYPE * restrict imgIn_row  = imgIn[i];
    DATA_TYPE * restrict y1_row     = y1[i];
    DATA_TYPE * restrict y2_row     = y2[i];
    DATA_TYPE * restrict out_row    = imgOut[i];

    /* Forward recursion along the row. */
    DATA_TYPE xm1 = SCALAR_VAL(0.0);
    DATA_TYPE ym1 = SCALAR_VAL(0.0);
    DATA_TYPE ym2 = SCALAR_VAL(0.0);

    for (int j = 0; j < h_; ++j)
    {
      const DATA_TYPE x = imgIn_row[j];
      const DATA_TYPE y = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;

      y1_row[j] = y;

      xm1 = x;
      ym2 = ym1;
      ym1 = y;
    }

    /* Backward recursion along the row. */
    DATA_TYPE xp1 = SCALAR_VAL(0.0);
    DATA_TYPE xp2 = SCALAR_VAL(0.0);
    DATA_TYPE yp1 = SCALAR_VAL(0.0);
    DATA_TYPE yp2 = SCALAR_VAL(0.0);

    for (int j = h_ - 1; j >= 0; --j)
    {
      const DATA_TYPE y = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
      y2_row[j] = y;

      const DATA_TYPE x = imgIn_row[j];
      xp2 = xp1;
      xp1 = x;
      yp2 = yp1;
      yp1 = y;
    }

    /* Combine horizontal forward and backward results for this row. */
    for (int j = 0; j < h_; ++j)
    {
      out_row[j] = c1 * (y1_row[j] + y2_row[j]);
    }
  }

  /* -------------------- Vertical pass (column-wise) -------------------- */
  /* For each column:
   *   - run forward recursion (writes y1)
   *   - run backward recursion (writes y2)
   *   - combine to produce final imgOut
   *
   * Columns are accessed with explicit pointer arithmetic using the
   * known row stride. This avoids 2D-indexing overhead and exposes
   * a simple, regular access pattern to the compiler.
   */
  for (int j = 0; j < h_; ++j)
  {
    /* Base pointers to the j-th column of each array. */
    DATA_TYPE * restrict col_out = &imgOut[0][j];
    DATA_TYPE * restrict col_y1  = &y1[0][j];
    DATA_TYPE * restrict col_y2  = &y2[0][j];

    /* Forward recursion along the column. */
    DATA_TYPE tm1 = SCALAR_VAL(0.0);
    DATA_TYPE ym1 = SCALAR_VAL(0.0);
    DATA_TYPE ym2 = SCALAR_VAL(0.0);

    DATA_TYPE * restrict p_out_f = col_out;
    DATA_TYPE * restrict p_y1_f  = col_y1;

    for (int i = 0; i < w_; ++i)
    {
      const DATA_TYPE out_val = *p_out_f;
      const DATA_TYPE y = a5 * out_val + a6 * tm1 + b1 * ym1 + b2 * ym2;

      *p_y1_f = y;

      tm1 = out_val;
      ym2 = ym1;
      ym1 = y;

      p_out_f += stride;
      p_y1_f  += stride;
    }

    /* Backward recursion along the column. */
    DATA_TYPE tp1 = SCALAR_VAL(0.0);
    DATA_TYPE tp2 = SCALAR_VAL(0.0);
    DATA_TYPE yp1 = SCALAR_VAL(0.0);
    DATA_TYPE yp2 = SCALAR_VAL(0.0);

    DATA_TYPE * restrict p_out_b = col_out + (w_ - 1) * stride;
    DATA_TYPE * restrict p_y2_b  = col_y2  + (w_ - 1) * stride;

    for (int i = w_ - 1; i >= 0; --i)
    {
      const DATA_TYPE y = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
      *p_y2_b = y;

      const DATA_TYPE out_val = *p_out_b;
      tp2 = tp1;
      tp1 = out_val;
      yp2 = yp1;
      yp1 = y;

      p_out_b -= stride;
      p_y2_b  -= stride;
    }

    /* Final combination for this column. */
    DATA_TYPE * restrict p_out_c = col_out;
    DATA_TYPE * restrict p_y1_c  = col_y1;
    DATA_TYPE * restrict p_y2_c  = col_y2;

    for (int i = 0; i < w_; ++i)
    {
      *p_out_c = c2 * (*p_y1_c + *p_y2_c);

      p_out_c += stride;
      p_y1_c  += stride;
      p_y2_c  += stride;
    }
  }

#pragma endscop
}


