            DATA_TYPE x  = imgIn_row[j];
            DATA_TYPE y  = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;
            y1_row[j]    = y;

            xm1 = x;
            ym2 = ym1;
            ym1 = y;
        }

        /* Backward recursion on row i (right-to-left). */
        xp1 = SCALAR_VAL(0.0);
        xp2 = SCALAR_VAL(0.0);
        yp1 = SCALAR_VAL(0.0);
        yp2 = SCALAR_VAL(0.0);

        for (j = h_limit - 1; j >= 0; j--) {
            DATA_TYPE y  = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;
            y2_row[j]    = y;

            xp2 = xp1;
            xp1 = imgIn_row[j];
