        DATA_TYPE *restrict imgOut_col = &imgOut_[0][j];
        DATA_TYPE *restrict y1_col     = &y1_[0][j];
        DATA_TYPE *restrict y2_col     = &y2_[0][j];

        /* Forward recursion down the column (i increasing). */
        tm1 = SCALAR_VAL(0.0);
        ym1 = SCALAR_VAL(0.0);
        ym2 = SCALAR_VAL(0.0);

        DATA_TYPE *po  = imgOut_col; /* pointer in imgOut_ */
        DATA_TYPE *py1 = y1_col;     /* pointer in y1_     */

        for (i = 0; i < w_limit; i++) {
            DATA_TYPE x = *po;
            DATA_TYPE y = a5 * x + a6 * tm1 + b1 * ym1 + b2 * ym2;

